import subprocessimport timeimport socketimport reimport shutilimport osimport copyimport sslimport randomimport mathimport asyncioimport ipaddressimport concurrent.futuresfrom dataclasses import dataclass, fieldfrom typing import List, Generator, Callable, Optional, Tuple, Set, Dictdef sync_hosts_to_user_list(self, hosts: List[str]):    r"""    Синхронизирует целевые хосты с файлом .\lists\list-general-user.txt,    чтобы winws.exe фильтровал и применял правила обхода DPI к этим адресам.    """    try:        bat_dir = os.path.dirname(os.path.abspath(self.bat_path)) if os.path.dirname(self.bat_path) else os.getcwd()        lists_dir = os.path.join(bat_dir, "lists")        user_list_path = os.path.join(lists_dir, "list-general-user.txt")        if not os.path.exists(lists_dir):            os.makedirs(lists_dir, exist_ok=True)        existing_lines = []        existing_hosts = set()        if os.path.exists(user_list_path):            with open(user_list_path, 'r', encoding='utf-8', errors='ignore') as f:                for line in f:                    line_str = line.strip()                    if line_str and not line_str.startswith("#"):                        existing_hosts.add(line_str.lower())                    existing_lines.append(line_str)        added_count = 0        for h in hosts:            cleaned = h.strip().lower()            if cleaned and cleaned not in existing_hosts:                existing_hosts.add(cleaned)                existing_lines.append(cleaned)                added_count += 1        if added_count > 0 or not os.path.exists(user_list_path):            with open(user_list_path, 'w', encoding='utf-8') as f:                for line in existing_lines:                    if line:                        f.write(f"{line}\n")            self.log(f"  [+] Добавлено {added_count} новых хостов в '{user_list_path}'")    except Exception as e:        self.log(f"  [!] Ошибка записи в list-general-user.txt: {e}")def is_valid_public_ip(ip_str: str) -> bool:    """Проверяет, что IP адрес является публичным (не loopback, private, bogon)."""    try:        ip = ipaddress.ip_address(ip_str)        return not (ip.is_private or ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_reserved)    except ValueError:        return Falsedef is_valid_domain(domain_str: str) -> bool:    """Проверяет базовую синтаксическую валидность доменного имени."""    if not domain_str or len(domain_str) > 253:        return False    if domain_str.startswith('.') or domain_str.endswith('.'):        return False    if not domain_str.replace('.', '').isdigit() and ('.' in domain_str or re.search(r'[a-zA-Z]', domain_str)):        return True    return False@dataclassclass WinwsParams:    tcp_split: int = 1    tcp_seqovl: int = 664    tcp_ttl: int = 0    udp_repeats: int = 8    udp_cutoff: str = "n4"    def to_key(self) -> Tuple[int, int, int, int, str]:        return (self.tcp_split, self.tcp_seqovl, self.tcp_ttl, self.udp_repeats, self.udp_cutoff)class FuzzerEngine:    def __init__(self,                 bat_path: str = "general (ALT11).bat",                 log_callback: Optional[Callable[[str], None]] = None,                 status_callback: Optional[Callable[[dict], None]] = None):        self.bat_path = bat_path        self.log_callback = log_callback or print        self.status_callback = status_callback        self.is_running = False        self.target_hosts: List[str] = []    def log(self, text: str):        if self.log_callback:            self.log_callback(text)    def set_status(self, **kwargs):        if self.status_callback:            self.status_callback(kwargs)    @staticmethod    def flush_dns_cache():        """Автоматическая очистка кэша DNS в Windows."""        try:            if os.name == 'nt':                subprocess.run("ipconfig /flushdns", shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)        except Exception:            pass    @staticmethod    def is_winws_alive() -> bool:        try:            output = subprocess.check_output('tasklist /FI "IMAGENAME eq winws.exe"', shell=True, stderr=subprocess.DEVNULL)            return b"winws.exe" in output        except subprocess.CalledProcessError:            return False    @staticmethod    def stop_winws():        """Остановка процесса winws.exe."""        os.system("taskkill /F /IM winws.exe >nul 2>&1")    @staticmethod    def reset_windivert():        """Очистка и сброс драйвера WinDivert при сбоях."""        os.system("taskkill /F /IM winws.exe >nul 2>&1")        if os.name == 'nt':            os.system("net stop WinDivert >nul 2>&1")            os.system("sc stop WinDivert >nul 2>&1")    @staticmethod    def start_winws(bat_path: str) -> bool:        """Запуск службы winws по выбранному батнику."""        if not os.path.exists(bat_path):            return False        FuzzerEngine.stop_winws()        time.sleep(0.5)        try:            if os.name == 'nt':                subprocess.Popen(["cmd.exe", "/c", bat_path], creationflags=subprocess.CREATE_NO_WINDOW)            else:                subprocess.Popen(["/bin/sh", bat_path])            time.sleep(1.5)            return FuzzerEngine.is_winws_alive()        except Exception:            return False    # --- Валидатор целей (Pre-flight Sanitizer) ---    @classmethod    def sanitize_and_filter_targets(cls, targets: List[str]) -> List[str]:        """        Предварительная валидация формата хостов:        - Сохраняет ВСЕ корректные доменные имена (например, t.me, discord.com), НЕ пытаясь подключаться к ним по TLS без winws (чтобы не отбраковывать заблокированные ресурсы!).        - Фильтрует битые строки, фантомные или непубличные IP (bogon, 127.0.0.1, 0.0.0.0).        """        valid_targets = []        seen = set()        for raw_target in targets:            cleaned = raw_target.strip().lower()            if not cleaned or cleaned in seen:                continue            is_ip = False            try:                ipaddress.ip_address(cleaned)                is_ip = True            except ValueError:                is_ip = False            if is_ip:                if is_valid_public_ip(cleaned):                    valid_targets.append(cleaned)                    seen.add(cleaned)            else:                if is_valid_domain(cleaned):                    valid_targets.append(cleaned)                    seen.add(cleaned)        return valid_targets    # --- Асинхронный сокет-движок проверки сокетов (TLS + QUIC) ---    @staticmethod    async def _async_probe_tls(host: str, port: int = 443, timeout: float = 3.0) -> Tuple[bool, float]:        """Асинхронная проверка TLS рукопожатия с отправкой SNI заголовка для доменов."""        start = time.time()        try:            ssl_ctx = ssl.create_default_context()            ssl_ctx.check_hostname = False            ssl_ctx.verify_mode = ssl.CERT_NONE            is_ip = False            try:                ipaddress.ip_address(host)                is_ip = True            except ValueError:                is_ip = False            sni_name = None if is_ip else host            reader, writer = await asyncio.wait_for(                asyncio.open_connection(host, port, ssl=ssl_ctx, server_hostname=sni_name),                timeout=timeout            )            elapsed = (time.time() - start) * 1000.0            writer.close()            await writer.wait_closed()            return True, round(elapsed, 1)        except Exception:            return False, 0.0    @staticmethod    async def _async_probe_quic(host: str, port: int = 443, timeout: float = 2.5) -> Tuple[bool, float]:        """Асинхронная проверка доступности по протоколу UDP / QUIC."""        start = time.time()        loop = asyncio.get_running_loop()        try:            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)            sock.setblocking(False)            dummy_payload = b'\x80\x00\x00\x01' + b'\x00' * 28            await loop.sock_sendto(sock, dummy_payload, (host, port))            data = await asyncio.wait_for(loop.sock_recv(sock, 1024), timeout=timeout)            elapsed = (time.time() - start) * 1000.0            sock.close()            return True, round(elapsed, 1)        except Exception:            try:                sock.close()            except Exception:                pass            return False, 0.0    @classmethod    async def probe_domain_combined_async(cls, host: str, timeout: float = 3.5) -> Tuple[bool, float, str]:        """Параллельное асинхронное тестирование TCP (TLS) и UDP (QUIC)."""        tls_task = asyncio.create_task(cls._async_probe_tls(host, timeout=timeout))        quic_task = asyncio.create_task(cls._async_probe_quic(host, timeout=timeout))        tls_ok, tls_lat = await tls_task        quic_ok, quic_lat = await quic_task        if tls_ok and quic_ok:            return True, min(tls_lat, quic_lat), "TCP+UDP"        elif tls_ok:            return True, tls_lat, "TLS"        elif quic_ok:            return True, quic_lat, "QUIC"        else:            return False, 0.0, "FAIL"    @classmethod    def probe_tls_connection(cls, host: str, port: int = 443, packets: int = 1, timeout: int = 3) -> Tuple[bool, float]:        """Синхронная обертка для обратной совместимости."""        try:            return asyncio.run(cls._async_probe_tls(host, port, timeout))        except Exception:            return False, 0.0    @classmethod    def probe_quic_udp(cls, host: str, port: int = 443, timeout: int = 3) -> Tuple[bool, float]:        """Синхронная обертка для обратной совместимости."""        try:            return asyncio.run(cls._async_probe_quic(host, port, timeout))        except Exception:            return False, 0.0    def extract_baseline(self) -> WinwsParams:        if not os.path.exists(self.bat_path):            raise FileNotFoundError(f"Файл '{self.bat_path}' не найден!")        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            content = f.read()        def get_val(pattern: str, default: int | str):            match = re.search(pattern, content)            return type(default)(match.group(1)) if match else default        return WinwsParams(            tcp_split=get_val(r'--dpi-desync-split-pos=(\d+)', 1),            tcp_seqovl=get_val(r'--dpi-desync-split-seqovl=(\d+)', 664),            tcp_ttl=get_val(r'--dpi-desync-ttl=(\d+)', 0),            udp_repeats=get_val(r'--dpi-desync-repeats=(\d+)', 8),            udp_cutoff=get_val(r'--dpi-desync-cutoff=([a-z0-9]+)', 'n4')        )    # --- Эвристический стратег мутаций ---    def generate_mutations(self, baseline: WinwsParams) -> Generator[WinwsParams, None, None]:        """Умный стратег мутаций с приоритетными синергетическими комбинациями."""        visited: Set[Tuple[int, int, int, int, str]] = set()        visited.add(baseline.to_key())        priority_combos = [            WinwsParams(tcp_split=2, tcp_seqovl=681, tcp_ttl=3, udp_repeats=6, udp_cutoff="n3"),            WinwsParams(tcp_split=3, tcp_seqovl=681, tcp_ttl=4, udp_repeats=8, udp_cutoff="d2"),            WinwsParams(tcp_split=2, tcp_seqovl=500, tcp_ttl=3, udp_repeats=10, udp_cutoff="n2"),            WinwsParams(tcp_split=4, tcp_seqovl=800, tcp_ttl=5, udp_repeats=6, udp_cutoff="d3"),            WinwsParams(tcp_split=1, tcp_seqovl=300, tcp_ttl=3, udp_repeats=12, udp_cutoff="n4"),            WinwsParams(tcp_split=3, tcp_seqovl=1000, tcp_ttl=7, udp_repeats=8, udp_cutoff="d4"),        ]        for combo in priority_combos:            key = combo.to_key()            if key not in visited:                visited.add(key)                yield combo        for pos in [2, 3, 4]:            for ttl in [3, 4, 5, 7]:                mutated = copy.copy(baseline)                mutated.tcp_split = pos                mutated.tcp_ttl = ttl                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for seq in [681, 500, 300, 800, 1000, 1200, 100]:            if seq != baseline.tcp_seqovl:                mutated = copy.copy(baseline)                mutated.tcp_seqovl = seq                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for pos in [2, 3, 4]:            if pos != baseline.tcp_split:                mutated = copy.copy(baseline)                mutated.tcp_split = pos                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for ttl in [3, 4, 5, 7, 8]:            if ttl != baseline.tcp_ttl:                mutated = copy.copy(baseline)                mutated.tcp_ttl = ttl                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for cutoff in ["n2", "n3", "d2", "d3", "d4"]:            if cutoff != baseline.udp_cutoff:                mutated = copy.copy(baseline)                mutated.udp_cutoff = cutoff                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for repeats in [6, 10, 12, 15, 4]:            if repeats != baseline.udp_repeats:                mutated = copy.copy(baseline)                mutated.udp_repeats = repeats                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated    def create_and_run_temp_bat(self, params: WinwsParams) -> str:        temp_bat = "_fuzzer_temp.bat"        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            lines = f.readlines()        clean_content = ""        for line in lines:            line_lower = line.strip().lower()            if line_lower.startswith("call service.bat status_zapret") or \                    line_lower.startswith("call service.bat check_updates"):                continue            clean_content += line        clean_content = re.sub(r'--dpi-desync-split-seqovl=\d+', f'--dpi-desync-split-seqovl={params.tcp_seqovl}', clean_content)        clean_content = re.sub(r'--dpi-desync-split-pos=\d+', f'--dpi-desync-split-pos={params.tcp_split}', clean_content)        clean_content = re.sub(r'--dpi-desync-repeats=\d+', f'--dpi-desync-repeats={params.udp_repeats}', clean_content)        clean_content = re.sub(r'--dpi-desync-cutoff=[a-z0-9]+', f'--dpi-desync-cutoff={params.udp_cutoff}', clean_content)        if params.tcp_ttl > 0 and "--dpi-desync-ttl" not in clean_content:            clean_content = re.sub(r'(--dpi-desync-split-pos=\d+)', rf'\1 --dpi-desync-ttl={params.tcp_ttl}', clean_content)        elif params.tcp_ttl > 0:            clean_content = re.sub(r'--dpi-desync-ttl=\d+', f'--dpi-desync-ttl={params.tcp_ttl}', clean_content)        with open(temp_bat, 'w', encoding='utf-8') as f:            f.write(clean_content)        subprocess.run(["cmd.exe", "/c", temp_bat], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)        return temp_bat    # --- Асинхронная вычисление с досрочным завершением (Early Exit) ---    async def _evaluate_config_async(self, target_domains: List[str], required_success: int) -> Tuple[int, List[Tuple[str, bool, float, str]]]:        passed_count = 0        failed_count = 0        total_hosts = len(target_domains)        results = []        semaphore = asyncio.Semaphore(16)        async def worker(domain: str):            nonlocal passed_count, failed_count            async with semaphore:                if not self.is_running:                    return domain, False, 0.0, "CANCEL"                if passed_count >= required_success or failed_count > (total_hosts - required_success):                    return domain, False, 0.0, "SKIPPED"                passed, latency, proto = await self.probe_domain_combined_async(domain, timeout=3.0)                if passed:                    passed_count += 1                else:                    failed_count += 1                return domain, passed, latency, proto        tasks = [asyncio.create_task(worker(dom)) for dom in target_domains]        for future in asyncio.as_completed(tasks):            if not self.is_running:                break            try:                res = await future                results.append(res)            except Exception:                pass        return passed_count, results    def evaluate_config(self, params: WinwsParams, target_domains: List[str], label: str = "МУТАЦИЯ", min_success_hosts: int = 8) -> bool:        self.log(f"\n[*] ТЕСТИРУЕМ: {label}")        self.log(f"    TCP: split={params.tcp_split}, seqovl={params.tcp_seqovl}, ttl={params.tcp_ttl}")        self.log(f"    UDP: repeats={params.udp_repeats}, cutoff={params.udp_cutoff}")        self.log(f"    Цели ({len(target_domains)}): {', '.join(target_domains[:6])}{'...' if len(target_domains)>6 else ''}")        self.set_status(params=params, current_step=label)        temp_bat = self.create_and_run_temp_bat(params)        time.sleep(2.0)        if not self.is_winws_alive():            self.log("  [!] ОШИБКА: Процесс winws.exe мгновенно завершился.")            if os.path.exists(temp_bat): os.remove(temp_bat)            return False        total_hosts = len(target_domains)        if total_hosts >= 12:            required_success = min(min_success_hosts, total_hosts)        else:            required_success = max(1, int(round(total_hosts * (min_success_hosts / 12.0))))        self.log(f"  [~] Асинхронный гибридный пробив (TCP+UDP) запущен (порог: {required_success}/{total_hosts})...")        start_time = time.time()        try:            passed_count, results = asyncio.run(self._evaluate_config_async(target_domains, required_success))        except Exception as e:            self.log(f"  [!] Ошибка асинхронного выполнения: {e}")            passed_count, results = 0, []        for domain, passed, latency, proto in results:            if proto == "SKIPPED":                continue            if passed:                status_str = f"[O] Доступен ({proto}, {latency:.0f} ms)"            else:                status_str = "[X] Заблокирован"            self.log(f"      -> {domain:35} {status_str}")        elapsed = time.time() - start_time        is_success = passed_count >= required_success        result_icon = "[+]" if is_success else "[-]"        self.log(f"  {result_icon} Результат: {passed_count}/{total_hosts} доступно за {elapsed:.1f} сек. (порог: {required_success})")        self.log("  [*] Очистка среды...")        self.stop_winws()        time.sleep(0.8)        if os.path.exists(temp_bat): os.remove(temp_bat)        return is_success    def patch_original_bat(self, params: WinwsParams):        backup_path = self.bat_path + ".bak"        if not os.path.exists(backup_path):            shutil.copy2(self.bat_path, backup_path)            self.log(f"\n  [i] Создан бэкап: {backup_path}")        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            content = f.read()        content = re.sub(r'--dpi-desync-split-seqovl=\d+', f'--dpi-desync-split-seqovl={params.tcp_seqovl}', content)        content = re.sub(r'--dpi-desync-split-pos=\d+', f'--dpi-desync-split-pos={params.tcp_split}', content)        content = re.sub(r'--dpi-desync-repeats=\d+', f'--dpi-desync-repeats={params.udp_repeats}', content)        content = re.sub(r'--dpi-desync-cutoff=[a-z0-9]+', f'--dpi-desync-cutoff={params.udp_cutoff}', content)        if params.tcp_ttl > 0 and "--dpi-desync-ttl" not in content:            content = re.sub(r'(--dpi-desync-split-pos=\d+)', rf'\1 --dpi-desync-ttl={params.tcp_ttl}', content)        elif params.tcp_ttl > 0:            content = re.sub(r'--dpi-desync-ttl=\d+', f'--dpi-desync-ttl={params.tcp_ttl}', content)        with open(self.bat_path, 'w', encoding='utf-8') as f:            f.write(content)        self.log(f"  [+] Конфиг '{os.path.basename(self.bat_path)}' успешно обновлен рабочими параметрами!")    def run_fuzzing(self, target_domains: List[str]):        self.is_running = True        try:            self.log("=== Zapret Fuzzer Engine (v2 Async) ===")            self.log(f"Всего целевых доменов/хостов: {len(target_domains)}")            self.log("[*] Очистка кэша DNS (ipconfig /flushdns)...")            FuzzerEngine.flush_dns_cache()            cleaned_targets = self.sanitize_and_filter_targets(target_domains)            if not cleaned_targets:                self.log("[!] Ошибка: Передан пустой или некорректный список хостов.")                self.set_status(state="FAILED", message="Некорректные цели")                return False            self.log(f"[+] Валидация списка завершена: {len(cleaned_targets)} уникальных доменов/IP подлежат проверке.")            self.target_hosts = cleaned_targets            baseline = self.extract_baseline()            self.log(f"Базовый конфиг извлекается из '{self.bat_path}'...")            sample_size = min(12, len(cleaned_targets))            current_targets = random.sample(cleaned_targets, sample_size) if cleaned_targets else []            if self.evaluate_config(baseline, current_targets, label="БАЗОВЫЙ КОНФИГ"):                self.log("\n[+] Базовый конфиг РАБОТАЕТ. Мутации не требуются.")                self.set_status(state="SUCCESS", message="Базовый конфиг работает!")                return True            self.log("\n[-] Базовый конфиг не сработал. Запуск эвристического подбора мутаций...")            for i, mutation in enumerate(self.generate_mutations(baseline), 1):                if not self.is_running:                    self.log("\n[!] Подбор остановлен пользователем.")                    self.set_status(state="STOPPED", message="Остановлено пользователем")                    return False                current_targets = random.sample(cleaned_targets, sample_size) if cleaned_targets else []                if self.evaluate_config(mutation, current_targets, label=f"МУТАЦИЯ #{i}"):                    self.log("\n[+] УСПЕХ! Найден оптимальный профиль параметров.")                    self.patch_original_bat(mutation)                    self.set_status(state="SUCCESS", message="Рабочая стратегия найдена и сохранена!", params=mutation)                    return True            self.log("\n[-] Все возможные мутации проверены. Рабочая стратегия не найдена.")            self.set_status(state="FAILED", message="Мутации исчерпаны")            return False        except Exception as e:            self.log(f"\n[!] Ошибка во время фуззинга: {e}")            self.set_status(state="ERROR", message=str(e))            return False        finally:            self.is_running = False    def stop(self):        self.is_running = False        self.stop_winws()